head.script:
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");} //팝업을 사용하기 위해 반드시 포함되어야 한다.
    //dataList1.getRowJSON와 같은 API 호출 시 반환 객체.
    window.rowJSON = {
        "addr": "서울시",
        "name": "손예진",
        "rowStatus": "R"
    };
    //popup에 넘길 data객체.
    window.dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array"
        data: rowJSON, // 전달 데이터 객체.
        name: "rowObj" // 변수명. popup에서 $w.getParameter( "rowObj" )로 깨내올 수 있다.
    };
    window.options = {
        id: "popup1",
        type: "litewindow",
        width: "230px",
        height: "250px",
        top: "130px",
        left: "200px",
        popupName: "openPopup1",
        modal: false,
        resizable: true,
        status: true,
        menubar: false,
        scrollbars: false,
        title: true,
        dataObject: dataObj
    };
    $w.openPopup("popup_TitleBar_SKT-735_(WSQ-2590)_popup.xml", options);
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
